import { test } from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

test('keeps http:// for a host with a port', () => {
  assert.equal(normalizeUrl('sindresorhus.com:123'), 'http://sindresorhus.com:123');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

test('drops only a single trailing dot from the hostname', () => {
  assert.equal(normalizeUrl('http://sindresorhus.com.'), 'http://sindresorhus.com');
  assert.equal(normalizeUrl('http://sindresorhus.com./foo'), 'http://sindresorhus.com/foo');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

test('keeps query parameters in the order they were written', () => {
  assert.equal(normalizeUrl('http://sindresorhus.com/?b=bar&a=foo'), 'http://sindresorhus.com/?b=bar&a=foo');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl, { toASCII } from '../index.js';

test('converts a Unicode hostname to punycode', () => {
  assert.equal(normalizeUrl(toASCII('http://bücher.example')), 'http://xn--bcher-kva.example');
});

